html:
{# ============================================================
   ITIHAD - DONATION ENTRY RECEIPT
   ERPNext / Frappe v15
   Custom HTML + Jinja Print Format
============================================================ #}


{# ============================================================
   DATA
============================================================ #}

{% set arabic_amount = frappe.db.get_value(
    "Donation Entry",
    doc.name,
    "custom_amount_in_words_arabic"
) or "" %}

{% if doc.payments %}
    {% set usd_amount = doc.payments
        | selectattr("currency", "equalto", "USD")
        | sum(attribute="donation_amount") %}
    {% set lbp_amount = doc.payments
        | selectattr("currency", "equalto", "LBP")
        | sum(attribute="donation_amount") %}
{% else %}
    {% set usd_amount = doc.donation_amount if doc.currency == "USD" else 0 %}
    {% set lbp_amount = doc.donation_amount if doc.currency == "LBP" else 0 %}
{% endif %}


{# Donor Phone #}
{% set donor_phone = "" %}

{% if doc.donor %}
    {% set donor_phone = frappe.db.get_value(
        "Donor",
        doc.donor,
        "custom_phone_numper"
    ) or "" %}
{% endif %}


{# User / Receiver #}
{% set user = frappe.get_doc("User", doc.owner) %}


{# ============================================================
   GREGORIAN DATE
   Example:
   2026 / 8 / 25
============================================================ #}

{% set gregorian_year = "" %}
{% set gregorian_month = "" %}
{% set gregorian_day = "" %}

{% if doc.posting_date %}

    {% set gparts = (doc.posting_date|string).split("-") %}

    {% if gparts|length == 3 %}

        {% set gregorian_year = gparts[0] %}
        {% set gregorian_month = gparts[1]|int %}
        {% set gregorian_day = gparts[2]|int %}

    {% endif %}

{% endif %}


{# ============================================================
   HIJRI DATE

   Expected custom field:
   custom_hijri_date

   Supports:
   1448/3/12
   1448-3-12
   12/3/1448
============================================================ #}

{% set hijri_date = doc.get("custom_hijri_date") or "" %}

{% set hijri_year = "" %}
{% set hijri_month = "" %}
{% set hijri_day = "" %}


{% if hijri_date %}

    {% set hijri_clean =
        hijri_date|string
        |replace("-", "/")
        |replace("هـ", "")
        |replace("ه", "")
        |trim
    %}

    {% set hparts = hijri_clean.split("/") %}


    {% if hparts|length == 3 %}


        {# YYYY/MM/DD #}
        {% if (hparts[0]|int) > 1000 %}

            {% set hijri_year = hparts[0]|int %}
            {% set hijri_month = hparts[1]|int %}
            {% set hijri_day = hparts[2]|int %}


        {# DD/MM/YYYY #}
        {% else %}

            {% set hijri_day = hparts[0]|int %}
            {% set hijri_month = hparts[1]|int %}
            {% set hijri_year = hparts[2]|int %}

        {% endif %}


    {% endif %}

{% endif %}



<style>

/* ============================================================
   REMOVE FRAPPE DEFAULT HEADING
============================================================ */

.print-heading,
.print-heading h2,
.print-heading h3,
.print-heading small,
.page-header,
.page-header h2,
.page-header h3,
.page-header small {
    display: none !important;
}


/* ============================================================
   PRINT PAGE
============================================================ */

.print-format {
    margin: 0 !important;
    padding: 0 !important;
}


/* ============================================================
   MAIN RECEIPT
============================================================ */

.receipt {

    width: 100%;

    position: relative;

    margin: 0;
    padding: 0;

    box-sizing: border-box;

    direction: rtl;

    color: #111;

    /*
       Font selected to resemble the original Arabic receipt.
    */

    font-family:
        "Traditional Arabic",
        "Arabic Typesetting",
        "Simplified Arabic",
        Arial,
        sans-serif !important;

    font-size: 20px;

    line-height: 1.25;
}


.receipt * {

    font-family:
        "Traditional Arabic",
        "Arabic Typesetting",
        "Simplified Arabic",
        Arial,
        sans-serif !important;
}


.receipt-main {

    margin-right: 90px;

    padding: 0 8px 0 4px;

    box-sizing: border-box;
}


/* ============================================================
   LABELS
============================================================ */

.form-label {

    font-size: 21px;

    font-weight: 700;

    white-space: nowrap;

    vertical-align: bottom;
}


/* ============================================================
   DOTTED FIELDS
============================================================ */

.dotted-value {

    display: inline-block;

    border-bottom: 1.5px dotted #222;

    min-height: 26px;

    vertical-align: bottom;

    padding:

        0
        5px
        1px
        5px;

    margin: 0;

    box-sizing: border-box;

    font-size: 20px;

    font-weight: 400;

    line-height: 24px;
}


/* ============================================================
   RECEIPT TITLE
============================================================ */

.receipt-title {

    width: 73%;

    margin: 0 auto;

    background: #000;

    color: #fff;

    padding:
        4px
        8px
        6px
        8px;

    box-sizing: border-box;

    direction: rtl;

    text-align: center;

    font-size: 31px;

    font-weight: 700;

    line-height: 1.1;
}


/* ============================================================
   VERTICAL ORGANIZATION NAME
============================================================ */

.organization-box {

    position: absolute;

    top: 0;

    right: 0;

    width: 76px;

    height: 445px;

    background: #fff;

    border: 2px solid #111;

    box-sizing: border-box;

    overflow: hidden;
}


.organization-name {

    width: 100%;

    height: 100%;

    display: flex;

    align-items: center;

    justify-content: center;

    writing-mode: vertical-rl;

    transform: rotate(180deg);

    font-size: 24px;

    font-weight: 700;

    line-height: 1.25;

    color: #111;

    text-align: center;
}


/* ============================================================
   DATE
============================================================ */

.date-label {

    font-size: 20px;

    font-weight: 700;

    white-space: nowrap;
}


.date-value {

    font-size: 19px;

    font-weight: 500;

    white-space: nowrap;
}


/* ============================================================
   BOTTOM INFORMATION
============================================================ */

.bottom-title {

    font-size: 20px;

    font-weight: 700;

    line-height: 1.15;
}


.bottom-name {

    margin-top: 1px;

    font-size: 19px;

    font-weight: 600;

    line-height: 1.15;
}


/* ============================================================
   PRINT
============================================================ */

@media print {

    .print-heading,
    .page-header {
        display: none !important;
    }


    .print-format {

        margin: 0 !important;

        padding: 0 !important;
    }


    .receipt {

        page-break-inside: avoid !important;
    }

}

</style>



<div class="receipt" dir="rtl">


    <!-- =====================================================
         RIGHT VERTICAL ORGANIZATION NAME
    ====================================================== -->

    <div class="organization-box">

        <div class="organization-name">

            جمعية الاتحاد الإسلامي

        </div>

    </div>



    <!-- =====================================================
         MAIN CONTENT
    ====================================================== -->

    <div class="receipt-main">


        <!-- =================================================
             TOP SECTION
        ================================================== -->

        <table
            style="
                width:100%;
                border-collapse:collapse;
                table-layout:fixed;
                direction:ltr;
                margin:0 0 15px 0;
            "
        >

            <tr>


                <!-- =========================================
                     LOGO
                ========================================== -->

                <td
                    style="
                        width:25%;
                        text-align:left;
                        vertical-align:middle;
                    "
                >

                    <img

                        src="https://i.imgur.com/gXUZcQd.png"

                        style="
                            display:block;

                            width:110px;
                            max-width:110px;

                            height:auto;

                            object-fit:contain;

                            filter:grayscale(100%);
                            -webkit-filter:grayscale(100%);
                        "
                    >

                </td>



                <!-- =========================================
                     RECEIPT TITLE + AMOUNT BOXES
                ========================================== -->

                <td
                    style="
                        width:75%;
                        text-align:center;
                        vertical-align:top;
                    "
                >


                    <!-- سند قبض -->

                    <div class="receipt-title">

                        سند قبض

                    </div>



                    <!-- =====================================
                         CURRENCY BOXES
                    ====================================== -->

                    <table
                        style="
                            width:73%;

                            margin:5px auto 0 auto;

                            border-collapse:separate;

                            border-spacing:4px 0;

                            table-layout:fixed;

                            direction:ltr;
                        "
                    >

                        <tr>


                            <!-- =============================
                                 USD AMOUNT
                            ============================== -->

                            <td
                                style="
                                    width:36%;
                                    height:40px;

                                    border:1.5px solid #222;

                                    text-align:center;
                                    vertical-align:middle;

                                    font-family:Arial,sans-serif !important;

                                    font-size:18px;
                                    font-weight:700;
                                "
                            >

                                {{ "{:,.2f}".format(usd_amount or 0) }}

                            </td>



                            <!-- USD SYMBOL -->

                            <td
                                style="
                                    width:12%;
                                    height:40px;

                                    border:1.5px solid #222;

                                    text-align:center;
                                    vertical-align:middle;

                                    font-family:Arial,sans-serif !important;

                                    font-size:20px;
                                    font-weight:700;
                                "
                            >

                                $

                            </td>



                            <!-- =============================
                                 LBP AMOUNT
                            ============================== -->

                            <td
                                style="
                                    width:36%;
                                    height:40px;

                                    border:1.5px solid #222;

                                    text-align:center;
                                    vertical-align:middle;

                                    font-family:Arial,sans-serif !important;

                                    font-size:18px;
                                    font-weight:700;
                                "
                            >

                                {{ "{:,.0f}".format(lbp_amount or 0) }}

                            </td>



                            <!-- LBP SYMBOL -->

                            <td
                                style="
                                    width:12%;
                                    height:40px;

                                    border:1.5px solid #222;

                                    text-align:center;
                                    vertical-align:middle;

                                    direction:rtl;

                                    font-size:18px;
                                    font-weight:700;
                                "
                            >

                                ل.ل.

                            </td>


                        </tr>

                    </table>


                </td>


            </tr>

        </table>



        <!-- =================================================
             DONOR NAME + PHONE
        ================================================== -->

        <table

            dir="rtl"

            style="
                width:100%;

                direction:rtl;

                border-collapse:collapse;

                table-layout:fixed;

                margin-top:5px;

                margin-bottom:6px;
            "
        >

            <tr>


                <!-- =========================================
                     DONOR
                ========================================== -->

                <td
                    style="
                        width:60%;

                        text-align:right;

                        vertical-align:bottom;

                        padding-left:10px;
                    "
                >


                    <span class="form-label">

                        وصلنا من:

                    </span>


                    <span

                        class="dotted-value"

                        style="
                            width:68%;
                            text-align:center;
                        "
                    >

                        {{ doc.donor_name or doc.donor or "" }}

                    </span>


                </td>



                <!-- =========================================
                     PHONE
                ========================================== -->

                <td
                    style="
                        width:40%;

                        text-align:right;

                        vertical-align:bottom;
                    "
                >


                    <span class="form-label">

                        رقم الهاتف:

                    </span>


                    <span

                        class="dotted-value"

                        dir="ltr"

                        style="
                            width:57%;

                            direction:ltr;

                            text-align:center;

                            font-family:Arial,sans-serif !important;

                            font-size:16px;
                        "
                    >

                        {{ donor_phone }}

                    </span>


                </td>


            </tr>

        </table>



        <!-- =================================================
             AMOUNT IN ARABIC WORDS
        ================================================== -->

        <div

            dir="rtl"

            style="
                width:100%;

                margin-top:1px;

                margin-bottom:6px;

                white-space:nowrap;
            "
        >


            <span class="form-label">

                مبلغ وقدره:

            </span>


            <span

                class="dotted-value"

                style="
                    width:79%;

                    text-align:right;

                    padding-right:5px;
                "
            >

                {{ arabic_amount | replace("\n", " - ") }}

            </span>


        </div>



        <!-- =================================================
             REMARKS
        ================================================== -->

        <div

            dir="rtl"

            style="
                width:100%;

                margin-top:1px;

                margin-bottom:8px;

                white-space:nowrap;
            "
        >


            <span class="form-label">

                وذلك لحساب:

            </span>


            <span

                class="dotted-value"

                style="
                    width:77%;

                    text-align:right;

                    padding-right:5px;
                "
            >

                {{ doc.remarks or "" }}

            </span>


        </div>



        <!-- =================================================
             SOLID DIVIDER
        ================================================== -->

        <div
            style="
                width:100%;

                border-top:3px solid #222;

                margin-top:14px;

                margin-bottom:10px;
            "
        >
        </div>



        <!-- =================================================
             BOTTOM INFORMATION
        ================================================== -->

        <table

            dir="rtl"

            style="
                width:100%;

                direction:rtl;

                border-collapse:collapse;

                table-layout:fixed;
            "
        >

            <tr>


                <!-- =========================================
                     DATE
                ========================================== -->

                <td
                    style="
                        width:40%;

                        text-align:right;

                        vertical-align:top;

                        padding:0 3px;
                    "
                >


                    <table

                        dir="rtl"

                        style="
                            width:100%;

                            direction:rtl;

                            border-collapse:collapse;
                        "
                    >


                        <!-- ================================
                             HIJRI DATE
                        ================================= -->

                        <tr>


                            <td

                                rowspan="2"

                                class="date-label"

                                style="
                                    width:29%;

                                    text-align:right;

                                    vertical-align:top;

                                    padding-top:1px;
                                "
                            >

                                التاريخ:

                            </td>



                            <td

                                dir="ltr"

                                class="date-value"

                                style="
                                    width:56%;

                                    direction:ltr;

                                    text-align:center;
                                "
                            >


                                {% if hijri_date %}

                                    {{ hijri_year }}
                                    /
                                    {{ hijri_month }}
                                    /
                                    {{ hijri_day }}

                                {% else %}

                                    &nbsp;&nbsp;&nbsp;&nbsp;
                                    /
                                    &nbsp;&nbsp;&nbsp;
                                    /
                                    &nbsp;&nbsp;&nbsp;

                                {% endif %}


                            </td>



                            <td
                                style="
                                    width:15%;

                                    text-align:center;

                                    font-size:19px;

                                    font-weight:700;
                                "
                            >

                                هـ

                            </td>


                        </tr>



                        <!-- ================================
                             GREGORIAN DATE
                        ================================= -->

                        <tr>


                            <td

                                dir="ltr"

                                class="date-value"

                                style="
                                    direction:ltr;

                                    text-align:center;
                                "
                            >


                                {% if doc.posting_date %}

                                    {{ gregorian_year }}
                                    /
                                    {{ gregorian_month }}
                                    /
                                    {{ gregorian_day }}

                                {% else %}

                                    &nbsp;&nbsp;&nbsp;&nbsp;
                                    /
                                    &nbsp;&nbsp;&nbsp;
                                    /
                                    &nbsp;&nbsp;&nbsp;

                                {% endif %}


                            </td>



                            <td
                                style="
                                    text-align:center;

                                    font-size:19px;

                                    font-weight:700;
                                "
                            >

                                م

                            </td>


                        </tr>


                    </table>


                </td>



                <!-- =========================================
                     TREASURER
                ========================================== -->

                <td
                    style="
                        width:30%;

                        text-align:center;

                        vertical-align:top;

                        padding:0 2px;
                    "
                >


                    <div class="bottom-title">
    أمين الصندوق
</div>

<div class="bottom-name">
    ماجدة تذكرجي
</div>

<div style="
    margin-top: 2px;
    text-align: center;
    height: 45px;
">
    <img
        src="https://i.imgur.com/t8U9lax.png"
        alt="توقيع أمين الصندوق"
        style="
            max-width: 115px;
            max-height: 43px;
            width: auto;
            height: auto;
            object-fit: contain;
        "
    >
</div>


                </td>



                <!-- =========================================
                     RECEIVER
                ========================================== -->

                <td
                    style="
                        width:30%;

                        text-align:center;

                        vertical-align:top;

                        padding:0 2px;
                    "
                >


                    <div class="bottom-title">

                        المستلم

                    </div>


                    <div
                        class="bottom-name"

                        style="
                            font-family:Arial,sans-serif !important;
                            font-size:16px;
                            font-weight:700;
                        "
                    >

                        {{ user.full_name or "" }}

                    </div>


                </td>


            </tr>

        </table>



        <!-- =================================================
             FOOTER
        ================================================== -->

        <div
            style="
                width:100%;

                margin-top:15px;

                border:1.5px solid #333;

                min-height:28px;

                padding:4px 6px;

                box-sizing:border-box;

                font-size:11px;

                font-weight:500;

                line-height:1.4;

                text-align:center;

                direction:rtl;

                white-space:nowrap;
            "
        >


            هاتف:

            بيروت:

            <span
                dir="ltr"
                style="font-family:Arial,sans-serif !important;"
            >
                01/644660 - 01/651990
            </span>


            &nbsp; - &nbsp;


            طرابلس:

            <span
                dir="ltr"
                style="font-family:Arial,sans-serif !important;"
            >
                06/442638
            </span>


            &nbsp; - &nbsp;


            البقاع:

            <span
                dir="ltr"
                style="font-family:Arial,sans-serif !important;"
            >
                03/819357
            </span>


            &nbsp; - &nbsp;


            صيدا:

            <span
                dir="ltr"
                style="font-family:Arial,sans-serif !important;"
            >
                07/735074
            </span>


            &nbsp; - &nbsp;


            <span
                dir="ltr"
                style="font-family:Arial,sans-serif !important;"
            >

                E-mail: itihad@itihad.org

            </span>


        </div>


    </div>

</div>
